const express = require('express');
const crypto = require('crypto');
const url = require('url');

const app = express();
const sessions = new Map();
const DEVICE_ID = 'iot-thermostat-7f3a';

// Trusted OAuth providers for IoT device pairing
const TRUSTED_ORIGINS = [
  'https://auth.smarthome.example.com',
  'https://accounts.iotcloud.example.com',
  'https://login.devicehub.example.com'
];

const DEVICE_SECRET = crypto.randomBytes(32).toString('hex');

function generateState() {
  return crypto.randomBytes(16).toString('hex');
}

function createSession(userId, provider) {
  const token = crypto.randomBytes(32).toString('hex');
  sessions.set(token, { userId, provider, created: Date.now(), deviceId: DEVICE_ID });
  return token;
}

// Normalize and validate redirect URI against trusted origins
function validateRedirectOrigin(redirectUri) {
  try {
    const parsed = new URL(redirectUri);
    const normalizedOrigin = parsed.origin.toLowerCase();

    for (const trusted of TRUSTED_ORIGINS) {
      const trustedParsed = new URL(trusted);
      const trustedOrigin = trustedParsed.origin.toLowerCase();

      // Check if the redirect origin matches a trusted origin
      if (normalizedOrigin === trustedOrigin) {
        return true;
      }
    }
    return false;
  } catch (e) {
    return false;
  }
}

// Validate the full redirect URL path and parameters
function validateRedirectPath(redirectUri) {
  try {
    const parsed = new URL(redirectUri);
    // Only allow specific callback paths
    const allowedPaths = ['/oauth/callback', '/auth/complete', '/device/pair'];
    return allowedPaths.includes(parsed.pathname);
  } catch (e) {
    return false;
  }
}

// Cross-service authentication: device requests token from cloud
function buildAuthorizationUrl(provider, redirectUri, state) {
  const authEndpoints = {
    'smarthome': 'https://auth.smarthome.example.com/authorize',
    'iotcloud': 'https://accounts.iotcloud.example.com/authorize',
    'devicehub': 'https://login.devicehub.example.com/authorize'
  };

  const endpoint = authEndpoints[provider];
  if (!endpoint) return null;

  return `${endpoint}?client_id=${DEVICE_ID}&redirect_uri=${encodeURIComponent(redirectUri)}&state=${state}&response_type=code`;
}

// Initiate OAuth flow for device pairing
app.get('/api/pair/initiate', (req, res) => {
  const { provider, redirect_uri } = req.query;

  if (!provider || !redirect_uri) {
    return res.status(400).json({ error: 'Missing required parameters' });
  }

  // Validate redirect URI origin
  if (!validateRedirectOrigin(redirect_uri)) {
    return res.status(403).json({ error: 'Untrusted redirect origin' });
  }

  // Validate redirect URI path
  if (!validateRedirectPath(redirect_uri)) {
    return res.status(403).json({ error: 'Invalid redirect path' });
  }

  const state = generateState();
  sessions.set(`state:${state}`, { provider, redirect_uri, created: Date.now() });

  const authUrl = buildAuthorizationUrl(provider, redirect_uri, state);
  if (!authUrl) {
    return res.status(400).json({ error: 'Unknown provider' });
  }

  res.json({ authorization_url: authUrl, state });
});

// OAuth callback handler
app.get('/oauth/callback', (req, res) => {
  const { code, state } = req.query;

  if (!code || !state) {
    return res.status(400).json({ error: 'Missing code or state' });
  }

  const stateData = sessions.get(`state:${state}`);
  if (!stateData) {
    return res.status(403).json({ error: 'Invalid state parameter' });
  }

  // Clean up used state
  sessions.delete(`state:${state}`);

  // Verify state hasn't expired (5 minute window)
  if (Date.now() - stateData.created > 300000) {
    return res.status(403).json({ error: 'State expired' });
  }

  // In production, exchange code for token with provider
  // For firmware, we create a local device session
  const sessionToken = createSession(`user_${code.substring(0, 8)}`, stateData.provider);

  // Redirect to the stored redirect_uri with the session
  const finalRedirect = `${stateData.redirect_uri}?session=${sessionToken}&device=${DEVICE_ID}`;
  res.redirect(302, finalRedirect);
});

// Device status endpoint (requires valid session)
app.get('/api/device/status', (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const token = authHeader.slice(7);
  const session = sessions.get(token);

  if (!session) {
    return res.status(401).json({ error: 'Invalid session' });
  }

  res.json({
    device_id: DEVICE_ID,
    status: 'online',
    temperature: 72,
    paired_user: session.userId,
    provider: session.provider
  });
});

// Firmware update check with cross-service auth
app.post('/api/firmware/check', (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const token = authHeader.slice(7);
  const session = sessions.get(token);

  if (!session) {
    return res.status(401).json({ error: 'Invalid session' });
  }

  res.json({
    current_version: '2.4.1',
    latest_version: '2.4.1',
    update_available: false
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '127.0.0.1', () => {
  console.log(`IoT Device firmware service running on port ${PORT}`);
});
